// Populate whole-file `source` on file-level nodes, and whole-class `source` on class-level
// nodes, by concatenating descendant function source (recursing through classes into their
// methods), so "Show Full File"/"Show Class" have something to render without hand-duplicating
// every function body above.
function collectDescendantSource(nodeId: string): string {
  const fixtureNode = FIXTURE_NODES[nodeId];
  if (!fixtureNode) return "";
  if (fixtureNode.level === "function") return fixtureNode.source ?? "";
  return fixtureNode.children
    .map(collectDescendantSource)
    .filter((source) => source.length > 0)
    .join("\n\n");
}

function languageForFileName(name: string): string | undefined {
  if (name.endsWith(".py")) return "python";
  if (name.endsWith(".ts") || name.endsWith(".tsx")) return "typescript";
  return undefined;
}

for (const fixtureNode of Object.values(FIXTURE_NODES)) {
  if (
    (fixtureNode.level === "file" || fixtureNode.level === "class") &&
    fixtureNode.children.length > 0 &&
    !fixtureNode.source
  ) {
    const source = collectDescendantSource(fixtureNode.node_id);
    if (source) {
      fixtureNode.source = source;
      fixtureNode.language =
        fixtureNode.level === "file"
          ? languageForFileName(fixtureNode.name)
          : languageForFileName(FIXTURE_NODES[fixtureNode.parent_id ?? ""]?.name ?? "");
    }
  }
}
